import random, subprocess, sys, tempfile
from pathlib import Path
REFERENCE='# External reference: statistics page /practice/27312/\n# Accepted submission: 52514507\n# Source: http://cs101.openjudge.cn/practice/solution/52514507/\n# License: not declared on the submission page; no license is inferred.\n\nn=int(input())\nlas=-1\ns=input()\nans=0\ni=0\nfan=""\nwhile i<=n-2:\n    if s[i]==s[i+1]:\n        i+=2\n        continue\n    elif s[i]=="H" and s[i+1]=="G":\n        if las!=1:\n            fan=fan+"1"\n            las=1\n        i+=2\n        continue\n    else:\n        if las!=0:\n            fan=fan+"0"\n            las=0\n        i+=2\n        continue\nif fan=="":\n    ans=0\nelif fan[0]=="1":\n    ans=len(fan)-len(fan)%2\nelse:\n    ans=len(fan)-(len(fan)+1)%2\nprint(ans)'
SAMPLE='14\nGGGHGHHGHHHGHG\n'
EXTRA_CASE='200000\\n'
GENERATOR_NAME='g27312'
def g27312(r):
    n = r.randrange(2, 10002, 2)
    return f"{n}\n{''.join(r.choice('GH') for _ in range(n))}\n"

def run(text):
    with tempfile.TemporaryDirectory(prefix='producecase-') as d:
        p=Path(d)/'main.py'; p.write_text(REFERENCE)
        x=subprocess.run([sys.executable,str(p)],input=text,text=True,capture_output=True,timeout=90)
        if x.returncode: raise SystemExit(x.stderr)
        return x.stdout
def scale_case(): return EXTRA_CASE
def main():
    d=Path('data'); d.mkdir(exist_ok=True)
    extra=scale_case(); cases=[SAMPLE]+([extra] if extra else [])+[globals()[GENERATOR_NAME](random.Random(s)) for s in range(1,21)]
    for i,c in enumerate(cases): (d/f'{i}.in').write_text(c); (d/f'{i}.out').write_text(run(c))
if __name__=='__main__': main()
